import React, { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { getUser } from '../../utils/auth';

const Sidebar = ({ onClose }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const user = getUser();
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [activeSection, setActiveSection] = useState('main');
  const [stats, setStats] = useState({
    totalBookings: 0,
    activeBookings: 0,
    pendingApprovals: 0,
    upcomingBookings: 0
  });

  const isActive = (path) => location.pathname === path;

  const handleLinkClick = () => {
    if (onClose) onClose();
  };

  // Simulate stats loading
  useEffect(() => {
    const loadStats = async () => {
      // Simulate API call
      setTimeout(() => {
        setStats({
          totalBookings: Math.floor(Math.random() * 50) + 10,
          activeBookings: Math.floor(Math.random() * 10) + 2,
          pendingApprovals: Math.floor(Math.random() * 5),
          upcomingBookings: Math.floor(Math.random() * 8) + 1
        });
      }, 1000);
    };

    loadStats();
  }, []);

  const getMenuSections = () => {
    if (!user) return {};

    const baseSection = {
      main: [
        { 
          name: 'Dashboard', 
          path: '/user/dashboard', 
          icon: '🏠',
          iconActive: '🏡',
          description: 'Overview & Analytics',
          badge: null,
          color: 'primary'
        },
        { 
          name: 'Buat Booking', 
          path: '/user/booking', 
          icon: '➕',
          iconActive: '✨',
          description: 'Buat reservasi baru',
          badge: 'New',
          color: 'success'
        },
        { 
          name: 'Booking Saya', 
          path: '/user/mybookings', 
          icon: '📋',
          iconActive: '📊',
          description: 'Kelola booking Anda',
          badge: stats.activeBookings > 0 ? stats.activeBookings : null,
          color: 'warning'
        }
      ]
    };

    if (user.role === 'admin') {
      return {
        admin: [
          { 
            name: 'Admin Dashboard', 
            path: '/admin/dashboard', 
            icon: '👑',
            iconActive: '💎',
            description: 'System overview',
            badge: null,
            color: 'primary'
          },
          { 
            name: 'Kelola Booking', 
            path: '/admin/bookings', 
            icon: '📊',
            iconActive: '📈',
            description: 'Manage all bookings',
            badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null,
            color: 'primary'
          },
          { 
            name: 'Kelola Ruangan', 
            path: '/admin/rooms', 
            icon: '🏢',
            iconActive: '🏗️',
            description: 'Room management',
            badge: null,
            color: 'success'
          },
          { 
            name: 'Kelola Users', 
            path: '/admin/users', 
            icon: '👥',
            iconActive: '👨‍👩‍👧‍👦',
            description: 'User management',
            badge: null,
            color: 'secondary'
          },
          { 
            name: 'Zoom Settings', 
            path: '/admin/zoom', 
            icon: '💻',
            iconActive: '🖥️',
            description: 'Zoom configuration',
            badge: null,
            color: 'primary'
          }
        ],
        ...baseSection
      };
    }

    if (user.role === 'zoom_approver') {
      return {
        zoom: [
          { 
            name: 'Zoom Dashboard', 
            path: '/zoom/dashboard', 
            icon: '💻',
            iconActive: '🖥️',
            description: 'Zoom overview',
            badge: null,
            color: 'primary'
          },
          { 
            name: 'Zoom Requests', 
            path: '/zoom/requests', 
            icon: '📝',
            iconActive: '✅',
            description: 'Pending approvals',
            badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null,
            color: 'warning'
          }
        ],
        ...baseSection
      };
    }

    if (user.role === 'room_approver') {
      return {
        room: [
          { 
            name: 'Room Dashboard', 
            path: '/room/dashboard', 
            icon: '🏢',
            iconActive: '🏗️',
            description: 'Room overview',
            badge: null,
            color: 'success'
          },
          { 
            name: 'Room Requests', 
            path: '/room/requests', 
            icon: '📝',
            iconActive: '✅',
            description: 'Pending approvals',
            badge: stats.pendingApprovals > 0 ? stats.pendingApprovals : null,
            color: 'warning'
          },
          { 
            name: 'Kelola Ruangan', 
            path: '/logistik/rooms', 
            icon: '🏢',
            iconActive: '🏗️',
            description: 'Manage facilities',
            badge: null,
            color: 'success'
          }
        ],
        ...baseSection
      };
    }

    return baseSection;
  };

  const getRoleInfo = () => {
    const roleMap = {
      admin: { 
        label: 'Administrator', 
        cssClass: 'role-admin',
        icon: '👑',
        level: 'System Admin',
        gradient: 'bg-gradient-to-r from-purple-500 to-purple-600'
      },
      zoom_approver: { 
        label: 'Zoom Approver', 
        cssClass: 'role-zoom',
        icon: '💻',
        level: 'Zoom Manager',
        gradient: 'bg-gradient-to-r from-blue-500 to-blue-600'
      },
      room_approver: { 
        label: 'Room Approver', 
        cssClass: 'role-room',
        icon: '🏢',
        level: 'Facility Manager',
        gradient: 'bg-gradient-to-r from-green-500 to-green-600'
      },
      user: { 
        label: 'User', 
        cssClass: 'role-user',
        icon: '👤',
        level: 'Employee',
        gradient: 'bg-gradient-to-r from-gray-500 to-gray-600'
      }
    };
    return roleMap[user?.role] || roleMap.user;
  };

  const getDisplayName = () => {
    if (user?.name) return user.name;
    if (user?.email) return user.email.split('@')[0];
    return 'User';
  };

  const menuSections = getMenuSections();
  const roleInfo = getRoleInfo();

  return (
    <div className={`sidebar h-full bg-white flex flex-col transition-all ${roleInfo.cssClass}`}>
      
      {/* Header with User Info */}
      <div className={`${roleInfo.gradient} relative overflow-hidden`}>
        {/* Background Pattern */}
        <div className="absolute inset-0 opacity-10">
          <div className="absolute inset-0" style={{
            backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.3'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`,
          }} />
        </div>
        
        <div className="relative p-6 text-white">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-3">
              <div className="relative">
                <div className="w-12 h-12 bg-white bg-opacity-20 rounded-2xl flex items-center justify-center backdrop-blur-sm transition-all hover-scale-sm">
                  <span className="text-2xl">{roleInfo.icon}</span>
                </div>
                <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-white flex items-center justify-center">
                  <div className="w-1.5 h-1.5 bg-white rounded-full animate-pulse"></div>
                </div>
              </div>
              
              <div className="min-w-0 flex-1">
                <h2 className="text-base font-bold truncate">
                  {getDisplayName()}
                </h2>
                <p className="text-xs opacity-90 truncate">
                  {user?.email}
                </p>
              </div>
            </div>
            
            {/* Collapse Toggle */}
            <button
              onClick={() => setIsCollapsed(!isCollapsed)}
              className="lg:hidden p-2 rounded-lg bg-white bg-opacity-20 hover:bg-opacity-30 transition-all"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
          </div>
          
          {/* Role Badge */}
          <div className="flex items-center justify-between">
            <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-white bg-opacity-20 text-white backdrop-blur-sm">
              <span className="mr-1">{roleInfo.icon}</span>
              {roleInfo.level}
            </span>
            
            {/* Status Indicator */}
            <div className="flex items-center space-x-1 text-xs opacity-90">
              <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
              <span>Online</span>
            </div>
          </div>
        </div>
      </div>

      {/* Interactive Stats Dashboard */}
      <div className="p-4 bg-gradient-to-br from-gray-50 to-white border-b border-gray-100">
        <div className="grid grid-cols-2 gap-3">
          <div className="card bg-white p-3 rounded-xl hover-lift transition-all cursor-pointer group">
            <div className="flex items-center space-x-2">
              <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform">
                <span className="text-white text-sm">📊</span>
              </div>
              <div>
                <div className="text-lg font-bold text-primary">{stats.totalBookings}</div>
                <div className="text-xs text-secondary">Total</div>
              </div>
            </div>
          </div>
          
          <div className="card bg-white p-3 rounded-xl hover-lift transition-all cursor-pointer group">
            <div className="flex items-center space-x-2">
              <div className="w-8 h-8 bg-success rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform">
                <span className="text-white text-sm">✅</span>
              </div>
              <div>
                <div className="text-lg font-bold text-success">{stats.activeBookings}</div>
                <div className="text-xs text-secondary">Active</div>
              </div>
            </div>
          </div>
        </div>
        
        {stats.pendingApprovals > 0 && (
          <div className="mt-3 p-3 alert alert-warning rounded-xl">
            <div className="flex items-center space-x-2">
              <span className="text-warning">⏳</span>
              <span className="text-sm font-medium">
                {stats.pendingApprovals} pending approval{stats.pendingApprovals > 1 ? 's' : ''}
              </span>
            </div>
          </div>
        )}
        
        {stats.upcomingBookings > 0 && (
          <div className="mt-2 p-3 bg-blue-50 border border-blue-200 rounded-xl">
            <div className="flex items-center space-x-2">
              <span className="text-blue-500">⏰</span>
              <span className="text-sm text-blue-700 font-medium">
                {stats.upcomingBookings} upcoming booking{stats.upcomingBookings > 1 ? 's' : ''}
              </span>
            </div>
          </div>
        )}
      </div>

      {/* Navigation Menu */}
      <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
        {Object.entries(menuSections).map(([sectionKey, items]) => (
          <div key={sectionKey} className="mb-6 animate-fade-in">
            <div className="flex items-center justify-between mb-3">
              <div className="text-xs font-bold text-secondary uppercase tracking-wider">
                {sectionKey === 'main' ? 'Personal' : 
                 sectionKey === 'admin' ? 'Administration' :
                 sectionKey === 'zoom' ? 'Zoom Management' :
                 sectionKey === 'room' ? 'Room Management' : sectionKey}
              </div>
              {sectionKey !== 'main' && (
                <div className="w-2 h-2 bg-gradient-primary rounded-full"></div>
              )}
            </div>
            
            {items.map((item) => (
              <Link
                key={item.path}
                to={item.path}
                onClick={handleLinkClick}
                className={`
                  group flex items-center space-x-3 p-3 rounded-xl transition-all duration-300 relative overflow-hidden hover-lift-lg
                  ${isActive(item.path)
                    ? 'bg-gradient-to-r from-white to-gray-50 shadow-md border-l-4 border-var(--role-color) text-var(--role-color)'
                    : 'text-gray-700 hover:bg-gradient-to-r hover:from-gray-50 hover:to-white hover:shadow-sm'
                  }
                `}
              >
                {/* Hover effect background */}
                <div className="absolute inset-0 bg-gradient-primary opacity-0 group-hover:opacity-5 transition-opacity duration-300"></div>
                
                <div className={`
                  relative w-11 h-11 rounded-xl flex items-center justify-center flex-shrink-0 transition-all duration-300
                  ${isActive(item.path)
                    ? `btn btn-${item.color} shadow-lg transform scale-105`
                    : 'bg-gray-100 group-hover:bg-gray-200 hover-scale'
                  }
                `}>
                  <span className="text-lg transition-all duration-300">
                    {isActive(item.path) ? item.iconActive : item.icon}
                  </span>
                  
                  {/* Badge */}
                  {item.badge && (
                    <div className={`
                      absolute -top-2 -right-2 min-w-5 h-5 badge badge-${item.color}
                      rounded-full flex items-center justify-center text-xs font-bold
                      transform scale-90 group-hover:scale-100 transition-transform duration-200
                    `}>
                      {typeof item.badge === 'number' && item.badge > 99 ? '99+' : item.badge}
                    </div>
                  )}
                </div>
                
                <div className="min-w-0 flex-1 relative">
                  <div className={`
                    font-semibold text-sm transition-colors duration-200
                    ${isActive(item.path) ? 'text-var(--role-color)' : 'text-gray-900 group-hover:text-gray-800'}
                  `}>
                    {item.name}
                  </div>
                  <div className="text-xs text-gray-500 mt-1 leading-tight group-hover:text-gray-600 transition-colors duration-200">
                    {item.description}
                  </div>
                </div>
                
                {/* Active indicator */}
                {isActive(item.path) && (
                  <div className="flex items-center space-x-1">
                    <div className={`w-2 h-2 bg-${item.color} rounded-full animate-pulse`}></div>
                  </div>
                )}
                
                {/* Arrow for non-active items */}
                {!isActive(item.path) && (
                  <svg className="w-4 h-4 text-gray-400 opacity-0 group-hover:opacity-100 transition-all duration-200 transform translate-x-2 group-hover:translate-x-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                  </svg>
                )}
              </Link>
            ))}
          </div>
        ))}
      </nav>

      {/* Quick Actions */}
      <div className="p-4 border-t border-gray-100 bg-gradient-to-br from-gray-50 to-white">
        <div className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center">
          <span>Quick Actions</span>
          <div className="ml-2 w-2 h-2 bg-gradient-success rounded-full"></div>
        </div>
        
        <div className="space-y-2">
          <button
            onClick={() => {
              navigate('/user/booking');
              handleLinkClick();
            }}
            className="btn btn-primary btn-md w-full hover-lift shadow-lg group"
          >
            <div className="w-5 h-5 mr-2 group-hover:scale-110 transition-transform">
              <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
              </svg>
            </div>
            <span>New Booking</span>
            <svg className="w-4 h-4 ml-auto opacity-70 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
            </svg>
          </button>
          
          <button
            onClick={() => {
              navigate('/user/profile');
              handleLinkClick();
            }}
            className="btn btn-secondary btn-md w-full hover-lift group"
          >
            <div className="w-5 h-5 mr-2 group-hover:scale-110 transition-transform">
              <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
